IF EXISTS(SELECT 1 FROM #GfChange0 r LEFT JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE t.[wItemID] IS NULL OR NOT(((t.[bItemCountry] IS NOT NULL AND r.BeforeValue IS NOT NULL AND t.[bItemCountry]=r.BeforeValue) OR (t.[bItemCountry] IS NULL AND r.BeforeValue IS NULL)) OR ((t.[bItemCountry] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bItemCountry]=r.AfterValue) OR (t.[bItemCountry] IS NULL AND r.AfterValue IS NULL)))) THROW 51000,'Gameforge normalization baseline changed: TITEMCHART.bItemCountry',1;
UPDATE t SET [bItemCountry]=r.AfterValue FROM dbo.[TITEMCHART] t JOIN #GfChange0 r ON t.[wItemID]=r.Id WHERE NOT ((t.[bItemCountry] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bItemCountry]=r.AfterValue) OR (t.[bItemCountry] IS NULL AND r.AfterValue IS NULL));
SET @changed=@changed+@@ROWCOUNT;
IF EXISTS(SELECT 1 FROM #GfChange0 r JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE NOT ((t.[bItemCountry] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bItemCountry]=r.AfterValue) OR (t.[bItemCountry] IS NULL AND r.AfterValue IS NULL))) THROW 51000,'Gameforge normalization postcondition failed: TITEMCHART.bItemCountry',1;
DROP TABLE #GfChange0;
SELECT @changed AS NormalizedOfficialClientFields;
COMMIT TRANSACTION;
